module mirror_checker(\n    input clk,\n    input rst_n,\n    input start,\n    input [127:0] string_in,\n    input [4:0] len,\n    output reg result,\n    output reg done\n);\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] CHECK = 2'd1;\n    localparam [1:0] DONE_ST = 2'd2;\n    \n    reg [1:0] state;\n    reg [1:0] next_state;\n    reg [3:0] i;\n    reg [3:0] next_i;\n    reg next_result;\n    reg next_done;\n    \n    function automatic is_in_set;\n        input [7:0] char;\n        begin\n            is_in_set = ((char == 8'h41) ||  // A\n                        (char == 8'h48) ||  // H\n                        (char == 8'h49) ||  // I\n                        (char == 8'h4D) ||  // M\n                        (char == 8'h4F) ||  // O\n                        (char == 8'h54) ||  // T\n                        (char == 8'h55) ||  // U\n                        (char == 8'h56) ||  // V\n                        (char == 8'h57) ||  // W\n                        (char == 8'h58) ||  // X\n                        (char == 8'h59));   // Y\n        end\n    endfunction\n    \n    always @(*) begin\n        next_state = state;\n        next_i = i;\n        next_result = result;\n        next_done = 1'b0;\n        \n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = CHECK;\n                    next_i = 4'd0;\n                    next_result = 1'b1;\n                end\n            end\n            \n            CHECK: begin\n                if (i >= len[4:1]) begin  // Half of (len >> 1)\n                    next_state = DONE_ST;\n                    next_done = 1'b1;\n                end else begin\n                    // Calculate indices\n                    reg [4:0] j;\n                    reg [7:0] left_char, right_char;\n                    j = (len - 5'd1) - i;\n                    \n                    left_char = string_in[i * 8 +: 8];\n                    right_char = string_in[j * 8 +: 8];\n                    \n                    if (!is_in_set(left_char)) begin\n                        next_result = 1'b0;\n                        next_state = DONE_ST;\n                        next_done = 1'b1;\n                    end else if (i != j) begin\n                        if (!is_in_set(right_char) || (left_char != right_char)) begin\n                            next_result = 1'b0;\n                            next_state = DONE_ST;\n                            next_done = 1'b1;\n                        end else begin\n                            next_i = i + 4'd1;\n                        end\n                    end else begin  // Middle character\n                        next_i = i + 4'd1;\n                    end\n                end\n            end\n            \n            DONE_ST: begin\n                next_done = 1'b1;\n                next_state = IDLE;\n            end\n            \n            default: begin\n                next_state = IDLE;\n            end\n        endcase\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            i <= 4'd0;\n            result <= 1'b0;\n            done <= 1'b0;\n        end else begin\n            state <= next_state;\n            i <= next_i;\n            result <= next_result;\n            done <= next_done;\n        end\n    end\nendmodule